/**
 * Evaluates a mathematical expression containing +, -, *, / with numbers
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 * @throws {Error} - If the expression is invalid or division by zero occurs
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Invalid expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Check for division by zero
    if (expr.includes('/0')) {
        throw new Error('Division by zero');
    }

    // Simple approach: use Function constructor to evaluate (but we need to be more careful)
    // For a proper implementation, we'd build a parser, but for simplicity we'll use eval
    // with validation to avoid security issues

    try {
        // Replace division by zero cases
        if (expr.includes('/0')) {
            throw new Error('Division by zero');
        }

        // Validate the expression structure
        // Check for consecutive operators (except for minus sign)
        if (/[\+\*\/]{2,}/.test(expr) || /^[\+\*\/]/.test(expr) || /[\+\*\/]$/.test(expr)) {
            throw new Error('Invalid expression');
        }

        // Check for balanced parentheses
        let parenCount = 0;
        for (let i = 0; i < expr.length; i++) {
            if (expr[i] === '(') parenCount++;
            if (expr[i] === ')') parenCount--;
            if (parenCount < 0) throw new Error('Invalid parentheses');
        }
        if (parenCount !== 0) throw new Error('Invalid parentheses');

        // Use Function constructor for safer evaluation
        // This approach avoids eval() security issues while still allowing basic math
        const result = new Function('return ' + expr)();

        // Check if result is a valid number
        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        if (e.message === 'Division by zero') {
            throw e;
        }
        throw new Error('Invalid expression');
    }
}

